def overlap_minutes(meetings: list[list[int]], k: int) -> int:
    if len(meetings) < k:
        return 0

    events: list[tuple[int, int]] = []
    for start, end in meetings:
        if start < end:
            events.append((start, 1))
            events.append((end, -1))

    events.sort()

    total = 0
    active = 0
    prev_t = 0
    for t, delta in events:
        if active >= k:
            total += t - prev_t
        active += delta
        prev_t = t

    return total
